#!/usr/bin/env node
// Seed GovernanceDB.team_members from team_members.json (generated by
// scripts/generate-team-members.mjs). IDEMPOTENT: upserts by (companyKey,
// memberKey), so re-running updates in place without creating duplicates.
//
// Adds the standard audit envelope (createdAt/By on insert, updatedAt/By always,
// isDeleted:false, version) and coerces int fields so the $jsonSchema validator
// accepts them. Targets ONLY GovernanceDB. Invents no data.
//
// Prereq: run `npm run db:provision:team-members` first (creates the validator).
// Usage:  npm run db:seed:team-members
import fs from 'node:fs';
import path from 'node:path';
import { MongoClient, Int32 } from 'mongodb';

const DEFAULT_DB_NAME = 'GovernanceDB';
const COLLECTION = 'team_members';
const ACTOR = 'migration:team-members';
const JSON_FILE = path.join(process.cwd(), 'team_members.json');

function resolveUri() {
  return (process.env.MONGODB_URI || process.env.CLAUDE_BRIDGE_MONGODB_URI || process.env.MONGO_BRIDGE_URI || '').trim();
}
function resolveDb() {
  return (process.env.MONGODB_DB_NAME || process.env.CLAUDE_BRIDGE_MONGODB_DB || process.env.MONGO_BRIDGE_DB || '').trim() || DEFAULT_DB_NAME;
}

/** Coerce section.number to a BSON int (or null) so it satisfies the validator. */
function coerceSections(sections) {
  return (Array.isArray(sections) ? sections : []).map((s) => ({
    number: s.number == null ? null : new Int32(Number(s.number)),
    title: String(s.title || ''),
    markdown: String(s.markdown || ''),
  }));
}

async function main() {
  const uri = resolveUri();
  const dbName = resolveDb();
  if (!uri) {
    console.error('✖ No connection string. Set MONGODB_URI (or CLAUDE_BRIDGE_MONGODB_URI) and retry.');
    process.exit(1);
  }
  if (!fs.existsSync(JSON_FILE)) {
    console.error(`✖ ${JSON_FILE} not found. Run \`npm run generate:team-members\` first.`);
    process.exit(1);
  }
  const docs = JSON.parse(fs.readFileSync(JSON_FILE, 'utf8'));
  if (!Array.isArray(docs) || !docs.length) {
    console.error('✖ team_members.json is empty.');
    process.exit(1);
  }

  const client = new MongoClient(uri, { serverSelectionTimeoutMS: 10_000, appName: 'governance-workbench-seed' });
  try {
    await client.connect();
    const db = client.db(dbName);
    const col = db.collection(COLLECTION);
    console.log(`→ Seeding ${docs.length} team member(s) into "${dbName}"."${COLLECTION}" ...`);

    const now = new Date();
    let inserted = 0;
    let updated = 0;
    for (const d of docs) {
      const companyKey = String(d.companyKey || 'MView');
      const memberKey = String(d.memberKey);
      const { createdAt: _c, createdBy: _cb, version: _v, _id: _id, ...domain } = d;
      const set = {
        ...domain,
        companyKey,
        memberKey,
        sections: coerceSections(d.sections),
        status: d.status || 'ACTIVE',
        isDeleted: false,
        updatedAt: now,
        updatedBy: ACTOR,
      };
      const res = await col.updateOne(
        { companyKey, memberKey },
        { $set: set, $setOnInsert: { createdAt: now, createdBy: ACTOR, version: new Int32(1) } },
        { upsert: true },
      );
      if (res.upsertedCount) inserted += 1; else updated += 1;
    }

    const total = await col.countDocuments({ companyKey: 'MView', isDeleted: false });
    console.log(`  ✔ Upsert complete: ${inserted} inserted, ${updated} updated.`);
    console.log(`  ℹ Live team_members for MView: ${total}.`);
    console.log('✔ Seeding complete.');
  } catch (err) {
    console.error('✖ Seeding FAILED.');
    console.error(`  ${err && err.message ? err.message : err}`);
    process.exitCode = 1;
  } finally {
    await client.close();
  }
}

main();
